// EVERYTHING YOU MAY WANT TO CHANGE IS IN THIS NODE.
return [{ json: {
  // Your GitHub user name and the repository that holds the feed
  owner: 'YOUR_GITHUB_USERNAME',
  repo: 'examprep-feed',
  branch: 'main',

  // The Claude model. claude-opus-5-5 writes the best notes and MCQs.
  // claude-sonnet-5-5 costs about half as much, claude-haiku-5-5 far less.
  model: 'claude-opus-5-5',

  hoursBack: 30,     // only stories published in the last 30 hours
  minPicks: 8,       // news cards per day, between these two numbers
  maxPicks: 15,
  minMcqs: 15,       // MCQs per day, between these two numbers
  maxMcqs: 30,

  // FULL TEXT. false = a must-read card shows ExamPrep's own summary and a link to the paper.
  // true = the card shows the paper's article word for word, under the paper's name and logo.
  // Switch a paper to true only from the day your signed agreement with it starts.
  // (Foreign Affairs puts only one line in its feed, so it has no full text to show.)
  fullText: {
    'Dawn': false,
    'The Express Tribune': false,
    'Foreign Affairs': false,
  },

  // Preferred sources first. Add or remove a line to change what is read.
  feeds: [
    { source: 'Dawn',               section: 'Editorial & Opinion', url: 'https://www.dawn.com/feeds/opinion' },
    { source: 'Dawn',               section: 'Front page',          url: 'https://www.dawn.com/feeds/home' },
    { source: 'Dawn',               section: 'National',            url: 'https://www.dawn.com/feeds/pakistan' },
    { source: 'Dawn',               section: 'International',       url: 'https://www.dawn.com/feeds/world' },
    { source: 'Dawn',               section: 'Business',            url: 'https://www.dawn.com/feeds/business' },
    { source: 'The Express Tribune', section: 'Editorial',          url: 'https://tribune.com.pk/feed/editorial' },
    { source: 'The Express Tribune', section: 'Opinion',            url: 'https://tribune.com.pk/feed/opinion' },
    { source: 'The Express Tribune', section: 'National',           url: 'https://tribune.com.pk/feed/pakistan' },
    { source: 'The Express Tribune', section: 'International',      url: 'https://tribune.com.pk/feed/world' },
    { source: 'The Express Tribune', section: 'Business',           url: 'https://tribune.com.pk/feed/business' },
    { source: 'Foreign Affairs',    section: 'Analysis',            url: 'https://www.foreignaffairs.com/rss.xml' },
  ],
} }];

// Reads every feed that came back, keeps the stories of the last day, and asks Claude which
// ones are worth a candidate's time. The article text is used only for this analysis: it is
// never saved or shown in the app.
const cfg = $('Config').first().json;
const feeds = $('Feeds').all();

const decode = s => String(s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#0?39;|&apos;|&rsquo;|&lsquo;/g, "'").replace(/&ldquo;|&rdquo;/g, '"')
  .replace(/&mdash;/g, '—').replace(/&ndash;/g, '–')
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n))
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ').replace(/<\/?[a-z][^>]*>/gi, ' ')   // feeds often escape their HTML
  .replace(/\s+/g, ' ').trim();
// The article as its own paragraphs. Used only for a source whose fullText switch is on in Config.
const paragraphs = (xml, t) => {
  const m = xml.match(new RegExp('<' + t + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + t + '>', 'i'));
  if (!m) return [];
  const html = m[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/<(script|style|figure|figcaption|iframe)[\s\S]*?<\/\1>/gi, ' ');
  return html.split(/<\/p>|<br\s*\/?>\s*<br\s*\/?>|<\/h[1-6]>|<\/li>/i).map(decode).filter(p => p.length > 1);
};
// "none@none.com (Mansoor Malik)" -> "Mansoor Malik"
const person = s => { const m = /\(([^)]+)\)\s*$/.exec(s); return (m ? m[1] : s.includes('@') ? '' : s).trim(); };
const tag = (xml, t) => {
  const m = xml.match(new RegExp('<' + t + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + t + '>', 'i'));
  return m ? decode(m[1]) : '';
};

const cut = Date.now() - cfg.hoursBack * 3600e3;
const seen = new Set();
const all = [];
$input.all().forEach((item, i) => {
  const feed = feeds[i] ? feeds[i].json : {};
  const xml = typeof item.json.data === 'string' ? item.json.data : '';
  (xml.match(/<item[\s>][\s\S]*?<\/item>/gi) || []).forEach(x => {
    const url = tag(x, 'link'), title = tag(x, 'title');
    if (!url || !title || seen.has(url)) return;
    const when = Date.parse(tag(x, 'pubDate'));
    if (when && when < cut) return;
    seen.add(url);
    const teaser = tag(x, 'description');
    const body = tag(x, 'content:encoded') || (teaser.length > 900 ? teaser : '');
    const full = (cfg.fullText || {})[feed.source] === true
      ? (paragraphs(x, 'content:encoded').length ? paragraphs(x, 'content:encoded') : paragraphs(x, 'description')) : [];
    all.push({ source: feed.source, section: feed.section, title, url,
               author: person(tag(x, 'dc:creator') || tag(x, 'author')),
               teaser: teaser.slice(0, 300), body: body.slice(0, 9000), when: when || 0,
               ...(full.join(' ').length > 600 ? { paras: full } : {}) });
  });
});
if (!all.length) throw new Error('No stories came back from any feed. Check the feed addresses in Config.');
const candidates = all.sort((a, b) => b.when - a.when).slice(0, 160).map((c, i) => ({ id: i + 1, ...c }));

const pkt = new Date(Date.now() + 5 * 3600e3).toISOString();   // Pakistan time
const date = pkt.slice(0, 10), time = pkt.slice(11, 16);

const system = `You are the news editor of ExamPrep, a study app for candidates of Pakistan's competitive examinations (CSS, PMS, FPSC, PPSC, SPSC and similar). Each morning you decide what a candidate should read from the day's newspapers, so that they can stop reading everything else.

You are given today's candidate stories as a numbered list: source, section, headline, author and a short teaser. Choose from this list only, and refer to stories by their id.

How to choose
Score every story from 0 to 2 on each of five things, for a total out of 10:
1. Syllabus link: Current Affairs, Pakistan Affairs, International Relations, or a likely essay theme.
2. Shelf life: still useful in next year's examination, not a one-day story.
3. Facts and figures: statistics, reports, treaties, laws, dates or appointments that can be quoted.
4. Author authority: a senior diplomat, economist, jurist or bureaucrat, or the paper's own editorial.
5. Exam likelihood: could become an MCQ, a short question, an essay topic or a précis passage.
A score of 8 to 10 is "must_read". A score of 5 to 7 is "skim". Leave out anything below 5.

Preferences
- Editorials and opinion first, then analysis, then hard news with lasting facts.
- Prefer Dawn, then The Express Tribune, then Foreign Affairs. Include the papers' unsigned editorials unless they score below 5.
- When two papers cover the same story, keep the better one only.
- Never choose city or metro news, letters to the editor, daily party gossip, talk-show quarrels, crime, showbiz, sport, or daily casualty counts.
- Return between ${cfg.minPicks} and ${cfg.maxPicks} picks. Fewer good ones are better than padding with weak ones.

The front-page summary
Separately, choose the headlines for the app's "News Summary": the 5 to 8 national stories and the 5 to 8 international stories a candidate should at least know happened today. These may include hard news that you did not pick for a full card. A story about Pakistan is national. Everything else, including Pakistan's dealings with other countries when the event is abroad, is international.`;

const list = candidates.map(c =>
  `${c.id}. [${c.source} · ${c.section}] ${c.title}${c.author ? ' — ' + c.author : ''}\n   ${c.teaser}`).join('\n');

const request = {
  model: cfg.model,
  max_tokens: 8000,
  fallbacks: 'default',
  system,
  messages: [{ role: 'user', content: `Today is ${date}. Here are the candidate stories.\n\n${list}` }],
  output_config: {
    effort: 'medium',
    format: { type: 'json_schema', schema: {
      type: 'object', additionalProperties: false, required: ['picks', 'national', 'international'],
      properties: {
        picks: { type: 'array', items: {
          type: 'object', additionalProperties: false, required: ['id', 'score', 'priority', 'reason'],
          properties: { id: { type: 'integer' }, score: { type: 'integer' },
                        priority: { type: 'string', enum: ['must_read', 'skim'] }, reason: { type: 'string' } } } },
        national: { type: 'array', items: { type: 'integer' } },
        international: { type: 'array', items: { type: 'integer' } },
      } } },
  },
};
return [{ json: { date, time, candidates, request } }];

// Takes Claude's choices and asks it to write the day: one card per chosen story, the
// front-page summary lines, and the MCQs.
const cfg = $('Config').first().json;
const prev = $('Candidates').first().json;
const res = $input.first().json;
if (res.stop_reason === 'refusal' || res.stop_reason === 'max_tokens')
  throw new Error('Choosing the stories stopped early: ' + res.stop_reason);
const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
const choice = JSON.parse(text);

const byId = new Map(prev.candidates.map(c => [c.id, c]));
const picks = (choice.picks || []).filter(p => byId.has(p.id)).slice(0, cfg.maxPicks);
if (!picks.length) throw new Error('No story was chosen today.');
const headlines = { national: (choice.national || []).filter(id => byId.has(id)),
                    international: (choice.international || []).filter(id => byId.has(id)) };

const system = `You write the daily study material of ExamPrep, an app for candidates of Pakistan's competitive examinations (CSS, PMS, FPSC, PPSC and similar). Your readers are preparing for Current Affairs, Pakistan Affairs, essay and MCQ papers. Many read English as a second language, so write short, plain sentences.

You are given today's chosen articles, each with its id and the text its publisher released, plus a list of headlines for the front-page summary. Write three things.

1. A card for every chosen article
- "summary": 3 or 4 short sentences in your own words that give the argument or the news, so that a reader knows what the piece says and can decide whether to open the original.
- "why": one line on why it matters for the examination.
- "key_facts": 3 to 6 facts a candidate could quote: figures, dates, names, laws, treaties, reports. One fact per item, complete in itself.
- "vocab": up to 3 less common words from the piece that are worth learning, each with a simple meaning. Leave it empty when there are none.
- "tags": 1 or 2 syllabus areas, for example Current Affairs, Pakistan Affairs, Foreign Policy, Economy, Environment, Governance, Security, International Relations, Science and Technology.

2. The front-page summary
For every headline id you are given, one entry: "headline", a short headline in your own words, and "line", one sentence of at most 25 words saying what happened and why it matters.

3. MCQs for the Current Affairs section
Write between ${cfg.minMcqs} and ${cfg.maxMcqs} MCQs from the facts in today's articles. Write as many as the day's solid facts support and no more: a quiet day gets fewer.
- Each tests one durable fact: who, what, when, where, how much, which body or law. Never test an opinion or a writer's argument.
- The question must stand alone months later. Say "In November 2026, which country …", never "according to the article" or "today".
- Four options, all plausible and of the same kind, exactly one correct. Put the correct option in a different position from question to question.
- "explanation": one or two sentences giving the fact and a little context, ending with the source name in brackets.
- "difficulty": Easy, Medium or Hard. "topic": one of Pakistan: Politics, Pakistan: Economy, Pakistan: Foreign Policy, International Affairs, Organisations and Treaties, Environment, Science and Technology, Appointments and Awards.

Rules that protect the reader and the newspapers
- Every fact must come from the text you were given. If you are not sure a figure or name is in the text, leave it out. Do not add facts from memory, because the reader will memorise what you write.
- Write everything in your own words. Never copy a sentence from an article. At most one short quotation per card, under 25 words, inside quotation marks.
- An article marked TEASER ONLY came with just its headline and a one-line summary. Write a shorter card from what those lines say, begin its summary with "From the published summary:", and write no MCQ from it.
- Refer to every article and headline by the id you were given.`;

const articles = picks.map(p => {
  const c = byId.get(p.id);
  const body = c.body && c.body.length > 600 ? c.body : '';
  return `=== ARTICLE id ${c.id} · ${c.source} · ${c.section}${c.author ? ' · ' + c.author : ''}${body ? '' : ' · TEASER ONLY'} ===\n${c.title}\n${body || c.teaser}`;
}).join('\n\n');
const heads = ['national', 'international'].map(k =>
  `${k.toUpperCase()}\n` + headlines[k].map(id => { const c = byId.get(id); return `${id}. ${c.title} (${c.source}) — ${c.teaser}`; }).join('\n')).join('\n\n');

const str = { type: 'string' };
const request = {
  model: cfg.model,
  max_tokens: 16000,
  fallbacks: 'default',
  system,
  messages: [{ role: 'user', content: `Today is ${prev.date}.\n\nCHOSEN ARTICLES\n\n${articles}\n\nHEADLINES FOR THE FRONT-PAGE SUMMARY\n\n${heads}` }],
  output_config: {
    effort: 'medium',
    format: { type: 'json_schema', schema: {
      type: 'object', additionalProperties: false, required: ['cards', 'summary', 'mcqs'],
      properties: {
        cards: { type: 'array', items: {
          type: 'object', additionalProperties: false, required: ['id', 'summary', 'why', 'key_facts', 'vocab', 'tags'],
          properties: { id: { type: 'integer' }, summary: str, why: str,
            key_facts: { type: 'array', items: str },
            vocab: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['word', 'meaning'], properties: { word: str, meaning: str } } },
            tags: { type: 'array', items: str } } } },
        summary: { type: 'array', items: {
          type: 'object', additionalProperties: false, required: ['id', 'headline', 'line'],
          properties: { id: { type: 'integer' }, headline: str, line: str } } },
        mcqs: { type: 'array', items: {
          type: 'object', additionalProperties: false, required: ['q', 'options', 'answer', 'explanation', 'difficulty', 'topic'],
          properties: { q: str, options: { type: 'array', items: str },
            answer: { type: 'string', enum: ['A', 'B', 'C', 'D'] }, explanation: str,
            difficulty: { type: 'string', enum: ['Easy', 'Medium', 'Hard'] }, topic: str } } },
      } } },
  },
};
return [{ json: { picks, headlines, request } }];

// Joins what Claude wrote to the real headline, link and source of each story (these come
// from the feed, never from the model), and prepares the day pack for the feed repository.
const cfg = $('Config').first().json;
const prev = $('Candidates').first().json;
const plan = $('Write request').first().json;
const res = $input.first().json;
if (res.stop_reason === 'refusal' || res.stop_reason === 'max_tokens')
  throw new Error('Writing the day stopped early: ' + res.stop_reason);
const out = JSON.parse((res.content || []).filter(b => b.type === 'text').map(b => b.text).join(''));

const byId = new Map(prev.candidates.map(c => [c.id, c]));
const pick = new Map(plan.picks.map(p => [p.id, p]));

const cards = (out.cards || []).filter(c => pick.has(c.id)).map(c => {
  const src = byId.get(c.id), p = pick.get(c.id);
  return { source: src.source, url: src.url, title: src.title, author: src.author, section: src.section,
           tags: c.tags, score: p.score, priority: p.priority, why: c.why, summary: c.summary,
           key_facts: c.key_facts, vocab: c.vocab,
           // the article itself, only for a must-read piece from a paper whose fullText switch is on
           ...(p.priority === 'must_read' && src.paras ? { text: src.paras } : {}) };
});
const line = s => { const src = byId.get(s.id); return { headline: s.headline, line: s.line, source: src.source, url: src.url }; };
const written = new Map((out.summary || []).filter(s => byId.has(s.id)).map(s => [s.id, s]));
const summary = {
  national: plan.headlines.national.filter(id => written.has(id)).map(id => line(written.get(id))),
  international: plan.headlines.international.filter(id => written.has(id)).map(id => line(written.get(id))),
};
const mcqs = (out.mcqs || []).filter(m => Array.isArray(m.options) && m.options.length === 4).slice(0, cfg.maxMcqs);
if (!cards.length) throw new Error('Claude returned no cards.');

const pack = { date: prev.date, time: prev.time, summary, cards, mcqs };
const file = `${prev.date}-${prev.time.replace(':', '')}.json`;
return [{ json: {
  file, cards: cards.length, mcqs: mcqs.length,
  github: { message: `Day pack ${prev.date}: ${cards.length} cards, ${mcqs.length} MCQs`,
            content: Buffer.from(JSON.stringify(pack, null, 1), 'utf8').toString('base64'),
            branch: cfg.branch },
} }];
